# Surah Al-Ma'ida (chapter 5) — part 12: ayat 111-120 (IDs 780-789)
SURAH = 5

ENTRIES = {
780: (
"اور جب میں نے — عیسیٰؑ کے — حواریوں (ایمان لانے والوں) کو — وحی بھیجی — (کہ) تم مجھ پر اور میرے رسول پر ایمان لاؤ — انہوں نے کہا: ہم ایمان لائے اور گواہ ہو جا کہ ہم — مسلمان — ہیں",
"""۱۔ حواریوں پر — وحی — ایمان لانے کا حکم۔
۲۔ ’’وَإِذْ أَوْحَيْتُ إِلَى الْحَوَارِيِّينَ أَنْ آمِنُوا بِي وَبِرَسُولِي قَالُوا آمَنَّا وَاشْهَدْ بِأَنَّنَا مُسْلِمُونَ‘‘ — اور جب میں نے — عیسیٰؑ کے — حواریوں (ایمان لانے والوں) کو — وحی بھیجی — (کہ) تم مجھ پر اور میرے رسول پر ایمان لاؤ — انہوں نے کہا: ہم ایمان لائے اور گواہ ہو جا کہ ہم — مسلمان — ہیں — یعنی حواری — ایمان لانے والے — مسلمان ہو گئے۔
۳۔ عملی سبق: اللہ اور رسول پر ایمان لاؤ؛ مسلمان ہو۔"""
),
781: (
"جب حواریوں نے کہا: اے عیسیٰ ابنِ مریم! کیا تیرا رب — تجھ پر — میرے لیے — آسمان سے ایک دسترخوان اتارے گا — عیسیٰؑ نے کہا: اللہ سے ڈرو — اگر تم ایمان والے ہو",
"""۱۔ حواریوں کا مطالبہ — آسمان سے دسترخوان۔
۲۔ ’’إِذْ قَالَ الْحَوَارِيُّونَ يَا عِيسَى ابْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَائِدَۃً مِّنَ السَّمَاءِ‘‘ — جب حواریوں نے کہا: اے عیسیٰ ابنِ مریم! کیا تیرا رب — تجھ پر — میرے لیے — آسمان سے ایک دسترخوان اتارے گا — یعنی حواریوں نے — اللہ کی قدرت پر شک نہیں کیا بلکہ — ایک نشانی طلب کی۔
۳۔ ’’قَالَ اتَّقُوا اللّٰہَ إِن كُنتُم مُّؤْمِنِينَ‘‘ — عیسیٰؑ نے کہا: اللہ سے ڈرو — اگر تم ایمان والے ہو — یعنی عیسیٰؑ نے غلو سے منع کیا۔
۴۔ عملی سبق: اللہ سے سوال — سنجیدگی سے کرو؛ غلو مت کرو۔"""
),
782: (
"انہوں نے کہا: ہم — اس سے — کھانا چاہتے ہیں — اور ہمارے دل مطمئن ہو جائیں — اور ہم جان لیں کہ آپ نے ہمیں سچی بات کہی — اور ہم — اس (دسترخوان) کے — گواہی دینے والوں — میں سے — ہوں",
"""۱۔ حواریوں کا ارادہ — نشانی سے تسلی۔
۲۔ ’’قَالُوا نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ الشَّاهِدِينَ‘‘ — انہوں نے کہا: ہم — اس سے — کھانا چاہتے ہیں — اور ہمارے دل مطمئن ہو جائیں — اور ہم جان لیں کہ آپ نے ہمیں سچی بات کہی — اور ہم — اس (دسترخوان) کے — گواہی دینے والوں — میں سے — ہوں — یعنی نشانی دیکھ کر ایمان مضبوط کرنا چاہتے تھے۔
۳۔ عملی سبق: نشانیوں کی طلب ایمان کی کمی نہیں — ایمان مضبوط کرنا جائز ہے۔"""
),
783: (
"عیسیٰ ابنِ مریم نے کہا: اے اللہ! ہمارے رب! ہم پر آسمان سے ایک دسترخوان اتار — وہ ہمارے لیے — ہمارے پہلے اور بعد والے لوگوں کے لیے — عید ہو — اور تیری طرف سے — نشانی — اور ہمیں رزق دے — اور تو ہی — سب سے بہتر رزق دینے والا ہے",
"""۱۔ عیسیٰؑ کی دعا — دسترخوان کی۔
۲۔ ’’قَالَ عِيسَى ابْنُ مَرْيَمَ اللّٰهُمَّ رَبَّنَا أَنزِلْ عَلَيْنَا مَائِدَۃً مِّنَ السَّمَاءِ‘‘ — عیسیٰ ابنِ مریم نے کہا: اے اللہ! ہمارے رب! ہم پر آسمان سے ایک دسترخوان اتار۔
۳۔ ’’تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَآخِرِنَا وَآيَۃً مِّنكَ‘‘ — وہ ہمارے لیے — ہمارے پہلے اور بعد والے لوگوں کے لیے — عید ہو — اور تیری طرف سے — نشانی — یعنی یہ دسترخوان — ایک عید اور ایک نشانی — دونوں ہو۔
۴۔ ’’وَارْزُقْنَا وَأَنتَ خَيْرُ الرَّازِقِينَ‘‘ — اور ہمیں رزق دے — اور تو ہی — سب سے بہتر رزق دینے والا ہے — یعنی اللہ ہی بہترین رزق دینے والا ہے۔
۵۔ عملی سبق: اللہ سے خیر مانگو؛ اللہ کی نعمتیں سب کے لیے ہیں۔"""
),
784: (
"اللہ نے فرمایا: بے شک میں — اس — تم پر اتاروں گا — پھر جو کوئی تم میں سے اس کے بعد کفر کرے — تو بے شک میں — اس — کو ایسا — عذاب دوں گا — جو جہانوں میں سے کسی کو نہ دوں گا",
"""۱۔ دسترخوان اتر آیا — مگر کفر کی سزا۔
۲۔ ’’قَالَ اللّٰہُ إِنِّي مُنَزِّلُهَا عَلَيْكُمْ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّي أُعَذِّبُهُ عَذَابًا لَّا أُعَذِّبُهُ أَحَدًا مِّنَ الْعَالَمِينَ‘‘ — اللہ نے فرمایا: بے شک میں — اس — تم پر اتاروں گا — پھر جو کوئی تم میں سے اس کے بعد کفر کرے — تو بے شک میں — اس — کو ایسا — عذاب دوں گا — جو جہانوں میں سے کسی کو نہ دوں گا — یعنی نشانی کے بعد کفر — سب سے بڑا گناہ ہے۔
۳۔ عملی سبق: اللہ کی نشانیاں دیکھ کر ایمان بڑھاؤ؛ کفر سے بچو۔"""
),
785: (
"اور جب اللہ نے کہا: اے عیسیٰ ابنِ مریم! کیا تم نے لوگوں سے کہا — مجھے اور میری ماں کو — اللہ کے سوا — دو معبود بنا لو — عیسیٰؑ نے کہا: تو پاک ہے — میرے لیے — یہ — جائز نہیں — (کہ) میں — وہ — کہوں جو میرے لیے — حق — نہیں — اگر میں نے کہا ہوتا تو تو جانتا — تو جانتا ہے جو میرے نفس میں ہے — اور میں — نہیں جانتا جو تیرے نفس میں ہے — بے شک تو ہی — سب — غیبوں کا جاننے والا ہے",
"""۱۔ قیامت کے دن — اللہ کا عیسیٰؑ سے سوال۔
۲۔ ’’وَإِذْ قَالَ اللّٰہُ يَا عِيسَى ابْنَ مَرْيَمَ أَأَنتَ قُلتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَٰهَيْنِ مِن دُونِ اللّٰہِ‘‘ — اور جب اللہ نے کہا: اے عیسیٰ ابنِ مریم! کیا تم نے لوگوں سے کہا — مجھے اور میری ماں کو — اللہ کے سوا — دو معبود بنا لو — یعنی قیامت کے دن کا سوال — عیسیٰؑ سے ہوگا۔
۳۔ ’’قَالَ سُبْحَانَكَ مَا يَكُونُ لِي أَنْ أَقُولَ مَا لَيْسَ لِي بِحَقٍّ‘‘ — عیسیٰؑ نے کہا: تو پاک ہے — میرے لیے — یہ — جائز نہیں — (کہ) میں — وہ — کہوں جو میرے لیے — حق — نہیں — یعنی عیسیٰؑ نے مکمل برات ظاہر کی۔
۴۔ ’’إِن كُنتُ قُلْتُهُ فَقَدْ عَلِمْتَهُ تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ إِنَّكَ أَنتَ عَلَّامُ الْغُيُوبِ‘‘ — اگر میں نے کہا ہوتا تو تو جانتا — تو جانتا ہے جو میرے نفس میں ہے — اور میں — نہیں جانتا جو تیرے نفس میں ہے — بے شک تو ہی — سب — غیبوں کا جاننے والا ہے — یعنی اللہ سب کچھ جانتا ہے۔
۵۔ عملی سبق: عیسیٰؑ خدا نہیں تھے — یہ قیامت کا سوال واضح کرے گا؛ غلو سے بچو۔"""
),
786: (
"میں نے — ان سے — سوائے وہی — کہا — جو تو نے مجھے حکم دیا — (کہ) اللہ کی عبادت کرو جو میرا رب اور تمہارا رب ہے — اور میں ان پر — گواہ — رہا جب تک میں ان میں تھا — پھر جب تو نے — مجھے — وفات دی — (تو) تو ہی — ان پر — نگہبان تھا — اور تو — ہر — چیز — پر — گواہ ہے",
"""۱۔ عیسیٰؑ کا جواب — توحید کی تبلیغ۔
۲۔ ’’مَا قُلْتُ لَهُمْ إِلَّا مَا أَمَرْتَنِي بِهِ أَنِ اعْبُدُوا اللّٰہَ رَبِّي وَرَبَّكُمْ‘‘ — میں نے — ان سے — سوائے وہی — کہا — جو تو نے مجھے حکم دیا — (کہ) اللہ کی عبادت کرو جو میرا رب اور تمہارا رب ہے — یعنی عیسیٰؑ کی تبلیغ صرف توحید تھی۔
۳۔ ’’وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي كُنتَ أَنتَ الرَّقِيبَ عَلَيْهِمْ‘‘ — اور میں ان پر — گواہ — رہا جب تک میں ان میں تھا — پھر جب تو نے — مجھے — وفات دی — (تو) تو ہی — ان پر — نگہبان تھا — یعنی عیسیٰؑ — تک — گواہ رہے۔
۴۔ ’’وَأَنتَ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ‘‘ — اور تو — ہر — چیز — پر — گواہ ہے۔
۵۔ عملی سبق: عیسیٰؑ کی تبلیغ توحید تھی؛ غلو مت کرو۔"""
),
787: (
"اگر تو انہیں عذاب دے — تو وہ تیرے بندے ہیں — اور اگر تو انہیں معاف کر دے — تو بے شک تو ہی — غلبہ والا — حکمت والا ہے",
"""۱۔ عیسیٰؑ کا اللہ کو اختیار — عذاب اور بخشش کا۔
۲۔ ’’إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ‘‘ — اگر تو انہیں عذاب دے — تو وہ تیرے بندے ہیں — اور اگر تو انہیں معاف کر دے — تو بے شک تو ہی — غلبہ والا — حکمت والا ہے — یعنی عیسیٰؑ نے فیصلہ اللہ کے سپرد کر دیا۔
۳۔ عملی سبق: فیصلہ اللہ پر چھوڑو؛ اللہ ہی عذاب اور بخشش کا مالک ہے۔"""
),
788: (
"اللہ نے فرمایا: آج — وہ دن — ہے جس میں — سچے لوگوں کی سچائی انہیں — فائدہ پہنچائے گی — ان کے لیے ایسی جنتیں جو نیچے سے نہریں بہتی ہیں — ہمیشہ رہیں گے — اللہ ان سے راضی ہوا — اور وہ اس سے راضی ہوئے — یہی — سب سے بڑی کامیابی ہے",
"""۱۔ قیامت کا دن — سچائی کا فائدہ۔
۲۔ ’’قَالَ اللّٰہُ هَٰذَا يَوْمُ يَنفَعُ الصَّادِقِينَ صِدْقُهُمْ‘‘ — اللہ نے فرمایا: آج — وہ دن — ہے جس میں — سچے لوگوں کی سچائی انہیں — فائدہ پہنچائے گی — یعنی قیامت کے دن سچائی کا اجر ملے گا۔
۳۔ ’’لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا‘‘ — ان کے لیے ایسی جنتیں جو نیچے سے نہریں بہتی ہیں — ہمیشہ رہیں گے۔
۴۔ ’’رَّضِيَ اللّٰہُ عَنْهُمْ وَرَضُوا عَنْهُ ذَٰلِكَ الْفَوْزُ الْعَظِيمُ‘‘ — اللہ ان سے راضی ہوا — اور وہ اس سے راضی ہوئے — یہی — سب سے بڑی کامیابی ہے — یعنی باہمی رضامندی — سب سے بڑی نجات ہے۔
۵۔ عملی سبق: سچائی اختیار کرو؛ اللہ کی رضا چاہو؛ سب سے بڑی کامیابی — اللہ کی رضا — ہے۔"""
),
789: (
"اللہ کی ہے آسمانوں اور زمین کی بادشاہی اور جو کچھ ان میں ہے — اور وہ — ہر چیز — پر — قدرت رکھتا ہے",
"""۱۔ مکمل بادشاہی — اللہ کی ہے۔
۲۔ ’’لِلّٰہِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ‘‘ — اللہ کی ہے آسمانوں اور زمین کی بادشاہی اور جو کچھ ان میں ہے — اور وہ — ہر چیز — پر — قدرت رکھتا ہے — یعنی اللہ ہی آسمانوں اور زمین کا مالک ہے۔
۳۔ عملی سبق: اللہ کی بادشاہی مانو؛ اسی پر بھروسہ کرو۔"""
),
}
